import{_ as a,o,c as i,a5 as r}from"./chunks/framework.BwlBv862.js";const b=JSON.parse('{"title":"Versión preliminar TikTools 4.2.1-rc.3","description":"","frontmatter":{"title":"Versión preliminar TikTools 4.2.1-rc.3","docId":"releases.4.2.1-rc.3","translationKey":"releases.4.2.1-rc.3","locale":"es","audience":"user","featureStatus":"experimental","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"3fa36e41656e0c6d288286b333984d1334fb5174054cdadb489464890c6196ea","translationRevision":"4d85212fc094dbc1035e10a7c6a4f584a99b77ed03c9b82e638e60731b8aa469","order":30},"headers":[],"relativePath":"es/releases/4.2.1-rc.3.md","filePath":"es/releases/4.2.1-rc.3.md","lastUpdated":1794611623000}'),s={name:"es/releases/4.2.1-rc.3.md"};function c(n,e,l,t,d,u){return o(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="tiktools-421-rc3" tabindex="-1">TikTools 4.2.1-rc.3 <a class="header-anchor" href="#tiktools-421-rc3" aria-label="Permalink to &quot;TikTools 4.2.1-rc.3 {#tiktools-421-rc3}&quot;">​</a></h1><h2 id="goal-release-status-and-prerequisites" tabindex="-1">Objetivo, estado de publicación y requisitos <a class="header-anchor" href="#goal-release-status-and-prerequisites" aria-label="Permalink to &quot;Objetivo, estado de publicación y requisitos {#goal-release-status-and-prerequisites}&quot;">​</a></h2><p>RC3 es una versión preliminar publicada, según el estado comunicado el 13 de noviembre de 2026. Úsala para evaluar los cambios Linux posteriores a RC2, con una copia de seguridad y un perfil de pruebas separado. Es un candidato, no una actualización del canal estable. Descarga el AppImage, DEB o paquete portátil publicado y su <code>SHA256SUMS.txt</code> desde la <a href="https://github.com/nglmercer/TikTools-app/releases" target="_blank" rel="noreferrer">lista de versiones</a>; los paquetes registrados se compilaron localmente.</p><p>La recuperación Cloud por sección y la colaboración siguen siendo experimentales. La instalación no despliega migraciones del backend ni acredita compatibilidad con cuentas de producción.</p><h2 id="changes-available-in-rc3" tabindex="-1">Cambios disponibles en RC3 <a class="header-anchor" href="#changes-available-in-rc3" aria-label="Permalink to &quot;Cambios disponibles en RC3 {#changes-available-in-rc3}&quot;">​</a></h2><ul><li>Conserva la corrección RC2 de lecturas simultáneas y el reintento local con el motivo nativo.</li><li>Variables guarda tipos text, number, boolean, list y secret local. El guardado atómico rechaza cambios de host o revisiones antiguas y conserva el renderizado de texto en plantillas existentes.</li><li>Los secretos siguen enmascarados. Cambiar de host no permite recurrir a una escritura antigua; la clasificación nativa excluye valores encolados antes de convertirse en secretos del envío posterior y de la comparación.</li><li>El puente nativo de Variables permite comparar caché, adoptar explícitamente una variable y descargar solo a caché. La aplicación vuelve a comprobar sesión, consentimiento, revisión local y entrada de caché.</li></ul><p>Guardar Variables sigue siendo local. RC3 no expone el botón completo Changes de Variables con envío/retirada revisados y gestión de conflictos pendientes; esa integración se describe en las <a href="./4.2.2.html">notas del código 4.2.2</a>. Marcar un valor local como secreto no borra una copia previamente publicada en Cloud.</p><h2 id="check-the-published-candidate" tabindex="-1">Comprobar el candidato publicado <a class="header-anchor" href="#check-the-published-candidate" aria-label="Permalink to &quot;Comprobar el candidato publicado {#check-the-published-candidate}&quot;">​</a></h2><ol><li>Verifica el checksum del paquete y la versión mostrada <code>4.2.1-rc.3</code>. Separa el perfil de pruebas y los directorios XDG del perfil habitual.</li><li>Crea una variable de texto inocua, por ejemplo <code>demoGreeting = &quot;Hello&quot;</code>, guarda y recarga. Comprueba los demás tipos con valores de muestra sin datos sensibles.</li><li>Abre Changes y prueba carga y reintento local. Revisa Settings/Teams y la ayuda opcional sin interpretar capacidades ausentes del backend como configuración correcta.</li><li>Informa de acción exacta, versión, motivo nativo e identificador de petición. Excluye tokens, códigos de invitación y valores secretos.</li></ol><h2 id="expected-result-evidence-and-recovery" tabindex="-1">Resultado esperado, evidencia y recuperación <a class="header-anchor" href="#expected-result-evidence-and-recovery" aria-label="Permalink to &quot;Resultado esperado, evidencia y recuperación {#expected-result-evidence-and-recovery}&quot;">​</a></h2><p>Los valores locales tipados deben conservarse al recargar y los cambios con host o revisión obsoletos deben fallar visiblemente. El registro original informa de pruebas nativas de Variables/sync/paridad, navegador con host simulado, CLI aislada, contenido de instaladores e inicio frontend-ready con un perfil vacío. No demuestra sincronización autenticada de producción ni reproducción multimedia.</p><p>El SHA-256 registrado del AppImage es <code>4b11260836457350debf2680b230c52cea8408ddf17ccdc729d0025a62149b7e</code>; verifica el archivo de checksums de tu descarga. Si falla, conserva el perfil copiado y consulta <a href="./../user/preferences/troubleshooting.html">solución de problemas</a> antes de reintentar recuperaciones.</p><p>Las invitaciones por apodo dependen del backend <code>6a69c99</code> y la migración <code>20261113000001_remote_invitation_recipients.sql</code>. El registro antiguo observó la ausencia de la ruta de personas; aquí no se afirma una nueva comprobación de producción. Faltaban transporte Cloud de Automations, revisiones Overlay y parte de la auditoría de colaboración; el responsable del bloqueo SQLite histórico seguía sin conocerse.</p><p>El <a href="https://github.com/nglmercer/TikTools-app/blob/80c5cb1fbfa45eaeb1c086c71320a15e565d8541/docs/RELEASE-4.2.1-rc.3.md" target="_blank" rel="noreferrer">registro original</a> se conserva como evidencia fechada. Vuelve al <a href="./">índice de versiones</a>.</p>',14)])])}const m=a(s,[["render",c]]);export{b as __pageData,m as default};
